import { buildings } from './data.js';
import { dimensions, periodCategories, categoryURL } from './catalog.js';
import { icon, media, esc } from './components.js';

export function home(renderCard){
 const examples={periods:'구석기에서 동시대까지',regions:'기후와 풍토가 빚은 공간',functions:'주거·신앙·문화, 공간의 쓰임',types:'움집·사찰·궁궐·공동주택'};
 const featured=['amsa','buseok','ddp'].map(id=>buildings.find(b=>b.id===id));
 const hahoe=buildings.find(b=>b.id==='hahoe'),mapo=buildings.find(b=>b.id==='mapo');
 return `<div class="wrap home-page">
 <section class="hero" aria-labelledby="hero-title">
  <div class="hero-copy"><div class="hero-kicker">KOREAN ARCHITECTURE ARCHIVE</div><h1 id="hero-title">공간을 읽고,<br><em>시간을 잇다.</em></h1><p>구석기의 거처에서 오늘의 도시까지.<br>시대와 지역, 쓰임을 따라<br class="hero-mobile-break"> 한국 건축의 이야기를 만나보세요.</p><div class="hero-buttons"><a class="button primary" href="/periods/">건축의 흐름 따라가기 ${icon('arrow')}</a><a class="button" href="/compare/">${icon('compare')} 두 건축 비교</a></div><div class="hero-stats"><div class="hero-stat"><strong>10</strong><span>시대의 흐름</span></div><div class="hero-stat"><strong>12</strong><span>건축의 종류</span></div><div class="hero-stat"><strong>${buildings.length}</strong><span>건축 기록</span></div></div></div>
  <figure class="hero-visual"><div class="hero-photo-frame"><img class="hero-photo" src="/assets/hero.jpg" alt="광화문과 경복궁의 전각들 너머로 북악산이 보이는 풍경" width="1920" height="1280" fetchpriority="high"><div class="hero-image-title"><span>SEOUL · GYEONGBOKGUNG</span><strong>산과 도시 사이,<br>이어지는 우리의 공간</strong></div><span class="hero-photo-index">ARCHIVE / 001</span></div><figcaption class="photo-caption"><span>서울 경복궁 · 광화문에서 북악산까지</span><a href="/library/photos/">사진 출처 ${icon('external')}</a></figcaption></figure>
 </section>
 <section class="home-paths" aria-labelledby="paths-title"><div class="section-head"><div><div class="eyebrow">FOUR WAYS TO EXPLORE</div><h2 id="paths-title">네 가지 시선으로 시작하기</h2><p>궁금한 관점을 고르면, 그에 맞는 기록이 펼쳐집니다.</p></div><span class="section-side-note">분류 → 건축 기록 → 비교와 배움</span></div><div class="perspective-grid">${Object.entries(dimensions).map(([id,d],i)=>`<a class="perspective-card perspective-${id}" href="/${id}/"><div class="perspective-card-top"><span class="perspective-icon">${icon(d.icon)}</span><span class="perspective-number">0${i+1}</span></div><div class="perspective-main"><div><h3>${d.name}</h3><p>${examples[id]}</p></div>${icon('arrow')}</div><div class="perspective-bottom"><span>${id==='regions'?'6개 권역 + 관련 문화권':d.categories.length+'개 분류'}</span><span>둘러보기 ${icon('arrow')}</span></div></a>`).join('')}</div></section>
 <section class="home-era-section" aria-labelledby="era-title"><div class="section-head"><div><div class="eyebrow">A JOURNEY THROUGH TIME</div><h2 id="era-title">어느 시대가 궁금한가요?</h2></div><a class="text-link" href="/periods/">시대별로 더 보기 ${icon('arrow')}</a></div><nav class="home-era-links" aria-label="시대 바로 가기">${periodCategories.map((e,i)=>`<a href="${categoryURL('periods',e.id)}"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(e.name)}</strong>${icon('arrow')}</a>`).join('')}</nav></section>
 <section class="home-featured" aria-labelledby="featured-title"><div class="section-head"><div><div class="eyebrow">SPACES TO READ</div><h2 id="featured-title">세 개의 공간으로 건축 읽기</h2><p>거처와 구조, 문화 공간의 변화를 한 걸음씩 살펴보세요.</p></div><a class="text-link" href="/types/">모든 종류 보기 ${icon('arrow')}</a></div><div class="cards-grid featured-grid">${featured.map(renderCard).join('')}</div></section>
 <section class="home-comparison" aria-labelledby="compare-home-title"><div class="home-comparison-copy"><div class="eyebrow">THEN & NOW</div><h2 id="compare-home-title">사진 너머의 차이까지,<br>나란히 비교해 보세요.</h2><p>재료는 어떻게 달라졌을까요?<br>그 안의 삶은 어떤 모습이었을까요?<br>두 공간을 같은 기준으로 읽으면 차이가 보입니다.</p><a class="button dark" href="/compare/?left=hahoe&right=mapo">한옥과 아파트 비교하기 ${icon('arrow')}</a></div><div class="home-comparison-visual"><div>${media(hahoe,'compare-home-photo')}<span>하회마을 <small>전통의 주거 공간</small></span></div><span class="home-comparison-between">${icon('compare')}</span><div>${media(mapo,'compare-home-photo')}<span>마포아파트 <small>산업화 시기의 공동주택</small></span></div></div></section>
 <div class="home-learning"><div>${icon('book')}<span><strong>낯선 건축 용어도, 천천히 알아가세요.</strong><span>용어집과 짧은 퀴즈가 건축 읽기를 도와드립니다.</span></span></div><a href="/library/glossary/" class="text-link">건축 용어집 ${icon('arrow')}</a></div></div>`;
}
